def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Basic type checks
    if not isinstance(fixity, list):
        raise TypeError(f"fixity must be a list, got {type(fixity).__name__}")

    if not isinstance(manifest_files, (set, list, tuple)):
        raise TypeError(f"manifest_files must be a set/list/tuple, got {type(manifest_files).__name__}")

    manifest_set = set(manifest_files)
    seen_files = set()
    errors = []

    required_keys = {"file", "hash", "hash_alg"}
    for idx, entry in enumerate(fixity):
        if not isinstance(entry, dict):
            errors.append(f"Entry {idx} is not a dict (type: {type(entry).__name__})")
            continue

        missing = required_keys - entry.keys()
        if missing:
            errors.append(f"Entry {idx} missing required key(s): {', '.join(sorted(missing))}")
            continue

        # Check file reference
        fname = entry.get("file")
        if not isinstance(fname, str) or not fname:
            errors.append(f"Entry {idx} has invalid 'file' value: {repr(fname)}")
        else:
            if fname not in manifest_set:
                errors.append(f"Entry {idx} references file '{fname}' not found in manifest")
            if fname in seen_files:
                errors.append(f"Duplicate fixity entry for file '{fname}' found at entry {idx}")
            seen_files.add(fname)

        # Validate hash
        h = entry.get("hash")
        if not isinstance(h, str) or not h:
            errors.append(f"Entry {idx} has invalid 'hash' value: {repr(h)}")

        # Validate hash algorithm
        algo = entry.get("hash_alg")
        if not isinstance(algo, str) or not algo:
            errors.append(f"Entry {idx} has invalid 'hash_alg' value: {repr(algo)}")

        # Optional size check
        size = entry.get("size")
        if size is not None and not isinstance(size, int):
            errors.append(f"Entry {idx} has non-integer 'size' value: {repr(size)}")

    if errors:
        raise ValueError("Fixity validation errors: " + "; ".join(errors))

    return True

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # The fixity block is expected to be a dictionary.
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary.")
    # It should contain a 'file' key with a list of file dictionaries.
    if 'file' not in fixity:
        raise ValueError("Fixity block is missing the 'file' key.")
    file_entries = fixity['file']
    if not isinstance(file_entries, list):
        raise ValueError("'file' key in fixity block must be a list.")
    # Track the names we have seen to detect duplicates.
    seen_names = set()
    for idx, entry in enumerate(file_entries):
        if not isinstance(entry, dict):
            raise ValueError(f"Entry #{idx} in 'file' list must be a dictionary.")
        # Each entry must specify at least the name of the file.
        if 'name' not in entry:
            raise ValueError(f"Entry #{idx} is missing the required 'name' key.")
        file_name = entry['name']
        if not isinstance(file_name, str):
            raise ValueError(f"The 'name' value in entry #{idx} must be a string.")
        # Entry may optionally contain a checksum; if present ensure it is a dict.
        if 'checksum' in entry:
            if not isinstance(entry['checksum'], dict):
                raise ValueError(f"The 'checksum' in entry #{idx} must be a dictionary.")
        # Verify that the referenced file exists in the manifest.
        if file_name not in manifest_files:
            raise ValueError(f"File '{file_name}' referenced in the fixity block is not present in the manifest.")
        # Detect duplicate references.
        if file_name in seen_names:
            raise ValueError(f"Duplicate reference to file '{file_name}' in the fixity block.")
        seen_names.add(file_name)
    return True

