        version_dirs is an array of version directory names and is assumed to be in
        version sequence (1, 2, 3...).
    """
    # Dictionary to hold mismatched digests: {version_dir: {file: (v_digest, root_digest)}}
    self.mismatched_digests = {}

    # Root inventory expected to be a dict mapping filename to digest
    root_inventory = getattr(self, 'root_inventory', {})

    base_dir = getattr(self, 'base_dir', '')

    for vdir in version_dirs:
        inv_path = os.path.join(base_dir, vdir, 'inventory.xml')
        if not os.path.exists(inv_path):
            raise ValueError(f"Missing inventory.xml in version directory '{vdir}'.")

        # Assume a helper method that loads the inventory into a dict
        inv = self.load_inventory(inv_path)

        # Compare each file digest in the version with the root inventory
        for fname, dig in inv.items():
            root_dig = root_inventory.get(fname)
            if root_dig is None:
                # File not in root inventory; ignore or handle as needed
                continue
            if dig != root_dig:
                self.mismatched_digests.setdefault(vdir, {})[fname] = (dig, root_dig)

        # Optionally ensure the inventory contains all root files
        for root_file in root_inventory:
            if root_file not in inv:
                raise ValueError(
                    f"Inventory in '{vdir}' is missing file '{root_file}' present in root inventory.")

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    # Normalise path
    try:
        abs_path = os.path.abspath(path)
    except Exception as exc:
        return f"error: cannot normalise path ({exc})"

    # Path must exist
    if not os.path.exists(abs_path):
        return "error: path does not exist"

    # If file, check naming convention
    if os.path.isfile(abs_path):
        base = os.path.basename(abs_path)
        if base.startswith('0='):
            return 'file'
        return f'file (not a Namaste file: {base})'

    # Must be a directory
    if not os.path.isdir(abs_path):
        return f'error: path is not a file or directory ({abs_path})'

    # Find Namaste files (0=*)
    try:
        entries = os.listdir(abs_path)
    except Exception as exc:
        return f"error: cannot list directory ({exc})"

    namaste_files = [
        f for f in entries
        if f.startswith('0=') and os.path.isfile(os.path.join(abs_path, f))
    ]

    if not namaste_files:
        return 'directory (no Namaste file)'

    # Inspect each Namaste file to infer type
    for fn in namaste_files:
        fp = os.path.join(abs_path, fn)
        try:
            with open(fp, 'r', encoding='utf-8') as f:
                data = f.read()
            # Try JSON
            try:
                import json as _json
            except Exception:
                # If json unavailable or fails, skip this file
                continue
            try:
                payload = _json.loads(data)
            except Exception:
                # Not JSON; maybe a simple key-value format
                if 'root' in data.lower():
                    return 'root'
                if 'object' in data.lower():
                    return 'object'
                continue

            # If JSON, look for obvious markers
            if isinstance(payload, dict):
                # Many OCFL inventories use top-level 'versionMajor' or 'root' keys
                if 'root' in payload:
                    return 'root'
                if 'object' in payload:
                    return 'object'
                # sometimes the file may contain a field describing type
                for key in payload:
                    if key.lower() == 'type':
                        val = str(payload[key]).lower()
                        if 'root' in val:
                            return 'root'
                        if 'object' in val:
                            return 'object'
            # Fallback if the file contains the string "root" or "object"
            if 'root' in data.lower():
                return 'root'
            if 'object' in data.lower():
                return 'object'
        except Exception as exc:
            # Skip problematic file, but do not fail entirely
            continue

    # If we cannot determine type from contents, give a best guess
    # Heuristic: if subdirectory named "segments" exists, it's likely an object,
    # otherwise it's likely a root.
    for sub in entries:
        sub_path = os.path.join(abs_path, sub)
        if os.path.isdir(sub_path):
            # check for segment subdirectories
            try:
                sub_entries = os.listdir(sub_path)
                if any(e.startswith('segment') for e in sub_entries):
                    return 'object'
            except Exception:
                continue

    return 'directory (type unknown)'

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""

    if not isinstance(params, dict):
        raise TypeError("params must be a dict")
    # Normalise bug_ids to a list of strings
    if isinstance(bug_ids, (list, tuple)):
        id_list = [str(bid) for bid in bug_ids if bid is not None]
    else:
        id_list = [str(bug_ids)] if bug_ids is not None else []
    if not id_list:
        return params
    # Bugzilla uses the 'ids' key for comma‑separated bug ids
    new_ids = ",".join(id_list)
    if 'ids' in params:
        existing = params['ids']
        if isinstance(existing, (list, tuple)):
            # Convert current values to strings and combine
            existing = [str(e) for e in existing]
            params['ids'] = ",".join(existing + id_list)
        else:
            params['ids'] = ",".join([str(existing), new_ids])
    else:
        params['ids'] = new_ids
    return params

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    if not isinstance(params, dict):
        raise TypeError("params must be a dictionary")

    # Add the bug ids to the parameters, handling single id or iterable
    if bug_ids:
        if isinstance(bug_ids, (list, tuple, set)):
            params['ids'] = ','.join(str(bid) for bid in bug_ids)
        else:
            params['ids'] = str(bug_ids)

    # Ensure a format is set (default to XML if not specified)
    if 'format' not in params:
        params['format'] = 'xml'

    # Optionally set a default for included fields if needed
    if 'include_fields' not in params:
        params['include_fields'] = '*'

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""

    if not isinstance(params, dict):
        raise TypeError("params must be a dictionary")

    # Normalize bug_ids to a list of strings
    if isinstance(bug_ids, str):
        bug_ids = [bid.strip() for bid in bug_ids.split(',') if bid.strip()]
    elif isinstance(bug_ids, (list, tuple, set)):
        bug_ids = [str(bid).strip() for bid in bug_ids if bid is not None]
    else:
        raise TypeError("bug_ids must be a string or iterable of ids")

    if not bug_ids:
        return params

    # Merge with any existing 'ids' entry
    existing_ids = params.get('ids', '')
    if existing_ids:
        # Split existing ids and combine
        existing_set = {bid.strip() for bid in existing_ids.split(',') if bid.strip()}
        combined = existing_set | set(bug_ids)
        params['ids'] = ','.join(sorted(combined))
    else:
        params['ids'] = ','.join(sorted(set(bug_ids)))

    return params

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.
    '''
    def merge_mapping_nodes(node_a, node_b):
        """
        Recursively merge the contents of two ruamel.yaml MappingNode objects.
        Modifies node_a in place and returns it.
        """
        for k_b, v_b in node_b.value:
            # Search for matching key in node_a
            for idx, (k_a, v_a) in enumerate(node_a.value):
                if k_a.value == k_b.value:
                    # Found duplicate key
                    if isinstance(v_a, MappingNode) and isinstance(v_b, MappingNode):
                        # Merge recursively
                        node_a.value[idx] = (k_a, merge_mapping_nodes(v_a, v_b))
                    else:
                        # Replace with new value
                        node_a.value[idx] = (k_a, v_b)
                    break
            else:
                # Key not present, append
                node_a.value.append((k_b, v_b))
        return node_a

    merged = {}
    for key_node, value_node in nodes:
        key = key_node.value
        if key in merged:
            _, existing_value = merged[key]
            if isinstance(existing_value, MappingNode) and isinstance(value_node, MappingNode):
                merged_mapping = merge_mapping_nodes(existing_value, value_node)
                merged[key] = (merged[key][0], merged_mapping)
            else:
                merged[key] = (key_node, value_node)
        else:
            merged[key] = (key_node, value_node)

    return list(merged.values())

def deep_merge_nodes(nodes):
    """
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.
    """
    def merge_nodes(old, new):
        # If both are MappingNode, merge recursively
        if isinstance(old, MappingNode) and isinstance(new, MappingNode):
            return merge_mapping_nodes(old, new)
        # Otherwise new value wins (override)
        return new

    def merge_mapping_nodes(old_map, new_map):
        # Build a lookup of old key -> (key_node, value_node)
        old_map_dict = {k.value: (k, v) for k, v in old_map.value}
        # Start with the old mapping entries
        merged_entries = list(old_map.value)

        for new_k_node, new_v_node in new_map.value:
            key_val = new_k_node.value
            if key_val in old_map_dict:
                old_k_node, old_v_node = old_map_dict[key_val]
                merged_v_node = merge_nodes(old_v_node, new_v_node)
                # Replace in the list at the position of the old key
                for idx, (k_node, _) in enumerate(merged_entries):
                    if k_node.value == key_val:
                        merged_entries[idx] = (old_k_node, merged_v_node)
                        break
            else:
                # New key, append
                merged_entries.append((new_k_node, new_v_node))
        return MappingNode(old_map.tag, merged_entries)

    merged = {}
    for key_node, val_node in nodes:
        key_val = key_node.value
        if key_val not in merged:
            merged[key_val] = (key_node, val_node)
        else:
            old_key_node, old_val_node = merged[key_val]
            new_val_node = merge_nodes(old_val_node, val_node)
            merged[key_val] = (old_key_node, new_val_node)

    # Reconstruct ordered list, keeping the first occurrence order
    seen = set()
    result = []
    for key_node, _ in nodes:
        key_val = key_node.value
        if key_val not in seen:
            result.append(merged[key_val])
            seen.add(key_val)
    return result

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    # Helper to merge two MappingNode instances
    def _merge_mapping_nodes(m1, m2):
        # Extract value lists from both MappingNodes
        seq1 = getattr(m1, 'value', [])
        seq2 = getattr(m2, 'value', [])
        # Build dicts keyed by ScalarNode.value
        merged_dict = {}
        merged_order = []
        # Helper to add sequence items
        def _process_seq(seq):
            for k_node, v_node in seq:
                k = getattr(k_node, 'value', None)
                if k in merged_dict:
                    # Merge if both are MappingNode, else last wins
                    existing = merged_dict[k]
                    if isinstance(existing, MappingNode) and isinstance(v_node, MappingNode):
                        merged_dict[k] = _merge_mapping_nodes(existing, v_node)
                    else:
                        merged_dict[k] = v_node
                else:
                    merged_dict[k] = v_node
                    merged_order.append(k)
        # Process seq1 first, then seq2 (seq2 overrides but merges)
        _process_seq(seq1)
        _process_seq(seq2)
        # Rebuild sequence preserving order
        new_seq = []
        # Preserve the original key nodes for already seen keys, else use those from seq2
        key_nodes = {}
        for k_node, _ in seq1:
            key_nodes[k_node.value] = k_node
        for k_node, _ in seq2:
            key_nodes[k_node.value] = k_node
        for k in merged_order:
            key_node = key_nodes.get(k, None)
            new_seq.append((key_node, merged_dict[k]))
        # Create a new MappingNode of same type as m1 (keep tag, anchors, etc.)
        new_map = type(m1)(tag=m1.tag, value=new_seq, anchor=m1.anchor, start_mark=m1.start_mark,
                           end_mark=m1.end_mark)
        return new_map

    # Main merging logic
    key_to_value = {}
    key_to_node = {}
    order = []

    for k_node, v_node in nodes:
        k = getattr(k_node, 'value', None)
        if k is None:
            continue  # skip invalid key
        if k in key_to_value:
            existing = key_to_value[k]
            # Deep merge if both are MappingNode
            if isinstance(existing, MappingNode) and isinstance(v_node, MappingNode):
                key_to_value[k] = _merge_mapping_nodes(existing, v_node)
            else:
                key_to_value[k] = v_node  # last wins
        else:
            key_to_value[k] = v_node
            key_to_node[k] = k_node
            order.append(k)

    result = []
    for k in order:
        result.append((key_to_node[k], key_to_value[k]))

    return result

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    flags = []
    for action in parser._actions:
        if action.option_strings:
            flags.extend(action.option_strings)
    return " ".join(flags)

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    flags = []
    for action in getattr(parser, '_actions', []):
        if action.option_strings:
            flags.extend(action.option_strings)
    return ' '.join(flags)

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    if not parser:
        return ''
    # Collect all option strings from the parser's actions
    option_strings = []
    for action in getattr(parser, '_actions', []):
        # Skip actions that do not define any flags (positional arguments)
        if hasattr(action, 'option_strings'):
            option_strings.extend(action.option_strings)
    # Remove duplicates while preserving order
    seen = set()
    unique_options = []
    for opt in option_strings:
        if opt not in seen:
            seen.add(opt)
            unique_options.append(opt)
    return ' '.join(unique_options)

def parse_arguments(*unparsed_arguments):
    """
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.
    """
    import argparse

    # Top‑level parser
    parser = argparse.ArgumentParser()
    # Subparsers handle commands; retaining the dest allows us to identify which
    # command was used.  No subcommands are added here – callers can extend this
    # parser as needed before invoking the function.
    subparsers = parser.add_subparsers(dest='subparser', required=False)

    # Parse the supplied arguments.  `parse_known_args` is used in case the
    # caller has added subparsers that are not recognised by this function.
    namespace, unknown = parser.parse_known_args(unparsed_arguments)

    # Build the mapping from the subparser name (if any) to the namespace.
    if getattr(namespace, 'subparser', None):
        return {namespace.subparser: namespace}
    else:
        return {'global': namespace}

def parse_subparser_arguments(unparsed_arguments, subparsers):
    '''
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    '''
    parsed = {}
    consumed_set = set()

    for name, parser in subparsers.items():
        try:
            namespace, remaining = parser.parse_known_args(unparsed_arguments)
            parsed[name] = namespace
            consumed_set.update([arg for arg in unparsed_arguments if arg not in remaining])
        except Exception:
            # If parsing fails, we ignore this subparser and leave its namespace unset
            continue

    remaining_args = [arg for arg in unparsed_arguments if arg not in consumed_set]
    return parsed, remaining_args

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
