                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''

    def merge_mapping_nodes(m1, m2):
        # Merge two MappingNode objects recursively.
        entries = list(m1.value)
        for k2, v2 in m2.value:
            # Find existing key in entries
            found = False
            for i, (k1, v1) in enumerate(entries):
                if getattr(k1, 'value', None) == getattr(k2, 'value', None):
                    found = True
                    if isinstance(v1, MappingNode) and isinstance(v2, MappingNode):
                        entries[i] = (k1, merge_mapping_nodes(v1, v2))
                    else:
                        entries[i] = (k1, v2)
                    break
            if not found:
                entries.append((k2, v2))
        return MappingNode(tag=m1.tag, value=entries)

    merged = []
    for key_node, val_node in nodes:
        # Find existing entry with same key value
        existing_index = None
        key_val = getattr(key_node, 'value', None)
        for idx, (k, _) in enumerate(merged):
            if getattr(k, 'value', None) == key_val:
                existing_index = idx
                break

        if existing_index is None:
            merged.append((key_node, val_node))
        else:
            existing_val = merged[existing_index][1]
            if isinstance(existing_val, MappingNode) and isinstance(val_node, MappingNode):
                merged_val = merge_mapping_nodes(existing_val, val_node)
            else:
                merged_val = val_node
            merged[existing_index] = (merged[existing_index][0], merged_val)

    return merged

def deep_merge_nodes(nodes):
    """
    Merge a sequence of node key/value pairs, merging duplicate keys.
    If a key has mapping values, merge the mapping contents recursively.
    Non-mapping values are overwritten by the last occurrence.
    """
    from collections import OrderedDict

    # Helper to detect a MappingNode by its tag
    def is_mapping(node):
        tag = getattr(node, "tag", "")
        return isinstance(tag, str) and tag.endswith("map")

    merged = OrderedDict()

    for key_node, value_node in nodes:
        # Preserve the original key node
        key = key_node.value
        if key not in merged:
            merged[key] = value_node
        else:
            existing = merged[key]
            if is_mapping(existing) and is_mapping(value_node):
                # Recursively merge two mappings
                merged_map = deep_merge_nodes(existing.value + value_node.value)
                existing.value = merged_map
            else:
                # Non-mapping value: last wins
                merged[key] = value_node

    return list(merged.items())

def deep_merge_nodes(nodes):
    """
    Merge a list of YAML node tuples that may contain duplicate keys.
    Duplicate keys are resolved by deep- merging MappingNodes; otherwise
    the last value wins.
    """
    def merge_mapping_nodes(map_a, map_b):
        """Return a new MappingNode with the deep merged contents of map_a and map_b."""
        # Preserve the tag from the first mapping node
        merged_value = _merge_pairs(map_a.value, map_b.value)
        return type(map_a)(tag=map_a.tag, value=merged_value)

    def _merge_pairs(list_a, list_b):
        """Merge two lists of (ScalarNode, Node) tuples."""
        merged = list_a[:]  # start with a's entries
        index_by_key = {k_node.value: i for i, (k_node, _) in enumerate(merged)}
        for k_node_b, v_node_b in list_b:
            key = k_node_b.value
            if key in index_by_key:
                i = index_by_key[key]
                _, v_node_a = merged[i]
                # If both are MappingNodes, recursively merge
                if isinstance(v_node_a, MappingNode) and isinstance(v_node_b, MappingNode):
                    merged[i] = (k_node_b, merge_mapping_nodes(v_node_a, v_node_b))
                else:
                    merged[i] = (k_node_b, v_node_b)  # last value wins
            else:
                merged.append((k_node_b, v_node_b))
                index_by_key[key] = len(merged) - 1
        return merged

    merged_nodes = []          # final result list
    key_to_index = {}          # maps key.value to index in merged_nodes

