def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    import re

    # Find all code block spans (```) to ignore tags inside them
    code_blocks = []
    for m in re.finditer(r'```.*?```', text, flags=re.S):
        code_blocks.append((m.start(), m.end()))

    tag_pattern = re.compile(r'\B#(?P<tag>\w+)\b')

    tags = set()

    def _replace(match):
        pos = match.start()
        # Skip replacement if inside a code block
        for start, end in code_blocks:
            if start <= pos < end:
                return match.group(0)
        tag = match.group('tag')
        tags.add(tag)
        if replacer:
            return replacer(tag)
        return match.group(0)

    replaced_text = tag_pattern.sub(_replace, text)

    return tags, replaced_text

def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    import re

    tags: Set[str] = set()

    # Find ranges of fenced code blocks (```...```)
    code_ranges: List[Tuple[int, int]] = []
    start = 0
    while True:
        start = text.find("```", start)
        if start == -1:
            break
        end = text.find("```", start + 3)
        if end == -1:
            # No closing fence; treat remainder as a block
            code_ranges.append((start, len(text)))
            break
        else:
            code_ranges.append((start, end + 3))
            start = end + 3

    def in_codeblock(pos: int) -> bool:
        """Return True if position is inside a fenced code block."""
        for s, e in code_ranges:
            if s <= pos < e:
                return True
        return False

    # Pattern for tags: '#tag', where tag consists of word characters.
    tag_pattern = re.compile(r"#\w+")
    if replacer is None:
        # No replacement needed: just collect tags
        for m in tag_pattern.finditer(text):
            if not in_codeblock(m.start()):
                tags.add(m.group()[1:])  # strip leading '#'
        return tags, text
    else:
        # Replacement: build new string incrementally
        result_parts: List[str] = []
        last = 0
        for m in tag_pattern.finditer(text):
            if not in_codeblock(m.start()):
                tag_word = m.group()
                replacement = replacer(tag_word)
                tags.add(tag_word[1:])  # strip leading '#'
                result_parts.append(text[last : m.start()])
                result_parts.append(replacement)
                last = m.end()
        result_parts.append(text[last:])
        return tags, "".join(result_parts)

